# iv = b"..."

n_size = 64

# ==========================================
# 2. FUNGSI my_prod ASLI
# ==========================================


def my_prod(A, B):
    n = len(A)
    z = (0,) * n

    def f(a, b, c, x):
        return (max(b[0], c[0]) + x,) + tuple(
            min(b[k-1], c[k-1]) + max(b[k], c[k]) - a[k-1]
            for k in range(1, n)
        )
    r = [z] * (n + 1)
    for row in A + B:
        s = [z]
        for j, x in enumerate(row, 1):
            s.append(f(r[j-1], r[j], s[-1], x))
        r = s
    p = [[None] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        p[i][n] = r[i]
    C = [[0] * n for _ in range(n)]
    for i in range(n-1, -1, -1):
        for j in range(n-1, i-1, -1):
            b = p[i][j+1]
            c = p[i+1][j] if i < j else b
            d = p[i+1][j+1]
            C[i][j] = C[j][i] = d[0] - max(b[0], c[0])
            p[i][j] = tuple(
                min(b[k], c[k]) +
                (max(b[k+1], c[k+1]) - d[k+1] if k+1 < n else 0)
                for k in range(n)
            )
    return C

# ==========================================
# 3. Z3 SOLVER DENGAN BIT-VECTOR OPTIMIZATION
# ==========================================


def solve_A_fast(G_val, AG_val, n=64):
    print("[*] Membangun model SAT menggunakan Bit-Vector...")
    s = Solver()

    # OPTIMASI: Gunakan BitVec(16) bukan Int() untuk membatasi ukuran memori
    A = [[BitVec(f'a_{i}_{j}', 16) for j in range(n)] for i in range(n)]

    total_sum = BitVecVal(0, 16)
    for i in range(n):
        for j in range(n):
            # Nilai dalam matriks tidak mungkin negatif dan pasti kecil
            s.add(A[i][j] >= 0)
            s.add(A[i][j] <= 256)
            if i < j:
                s.add(A[i][j] == A[j][i])
            total_sum += A[i][j]

    s.add(total_sum == 256)

    def z3_max(a, b): return If(a > b, a, b)
    def z3_min(a, b): return If(a < b, a, b)

    z = tuple([BitVecVal(0, 16)] * n)

    def f_z3(a, b, c, x):
        res = [z3_max(b[0], c[0]) + x]
        for k in range(1, n):
            res.append(z3_min(b[k-1], c[k-1]) + z3_max(b[k], c[k]) - a[k-1])
        return tuple(res)

    r = [z] * (n + 1)

    # State A (BitVec Variables)
    for row in A:
        st = [z]
        for j, x in enumerate(row, 1):
            st.append(f_z3(r[j-1], r[j], st[-1], x))
        r = st

    # State G (Constants)
    for row in G_val:
        st = [z]
        for j, x in enumerate(row, 1):
            st.append(f_z3(r[j-1], r[j], st[-1], BitVecVal(x, 16)))
        r = st

    p = [[None] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        p[i][n] = r[i]

    for i in range(n-1, -1, -1):
        for j in range(n-1, i-1, -1):
            b = p[i][j+1]
            c = p[i+1][j] if i < j else b
            d = p[i+1][j+1]

            val = d[0] - z3_max(b[0], c[0])
            s.add(val == BitVecVal(AG_val[i][j], 16))

            new_p = []
            for k in range(n):
                term1 = z3_min(b[k], c[k])
                term2 = z3_max(b[k+1], c[k+1]) - d[k+1] if k + \
                    1 < n else BitVecVal(0, 16)
                new_p.append(term1 + term2)
            p[i][j] = tuple(new_p)

    print("[*] Mengeksekusi solver SAT (jauh lebih cepat)...")
    if s.check() == sat:
        print("[+] Matriks A berhasil ditemukan!")
        m = s.model()
        return [[m[A[i][j]].as_long() for j in range(n)] for i in range(n)]
    else:
        raise Exception("[-] Solver gagal.")


# ==========================================
# 4. EKSEKUSI
# ==========================================
if __name__ == "__main__":
    A_matrix = solve_A_fast(G, AG, n_size)

    print("[*] Menghitung shared secret AGB...")
    AGB = my_prod(A_matrix, GB)

    print("[*] Mendekripsi ciphertext...")
    shared_secret = SHA256.new(str(AGB).encode()).digest()[:128]
    cipher = AES.new(shared_secret, AES.MODE_CBC, iv)

    try:
        recovered_flag = unpad(cipher.decrypt(ct), 16)
        print("\n[+] FLAG DITEMUKAN:")
        print(recovered_flag.decode())
    except Exception as e:
        print("\n[-] Gagal mendekripsi flag:", e)
